export const code = async (inputs) => {
  const rows = inputs.rows;

  const departments = {};

  for (const item of rows) {
    const emp = item.values;
    const dept = emp["Department"] || "Unassigned";

    if (!departments[dept]) {
      departments[dept] = [];
    }

    departments[dept].push({
      employee_id: emp["Employee ID"] || "",
      name: emp["Name"] || "",
      email: emp["Email "]?.trim() || "",
      role: emp["Role"] || "",
      slack_id : emp["Slack ID"] || "",
      backup: emp["Backup Employee"] || null
    });
  }

  return { departments };
};

export const code = async (inputs) => {
  const departments = inputs.departments;
  const mailDept = (inputs.mailDept || "").trim().toLowerCase();

  if (!departments) {
    return {
      department: null,
      matched: false,
      employees: [],
      error: "Missing departments input"
    };
  }

  const normalizedDepts = Object.fromEntries(
    Object.entries(departments).map(([k, v]) => [k.trim().toLowerCase(), v])
  );

  const matchedKey = mailDept ? normalizedDepts[mailDept] ? mailDept : null : null;

  const finalKey = matchedKey || (normalizedDepts["general"] ? "general" : null);

  const matched = finalKey ? normalizedDepts[finalKey] : [];

  return {
    department: finalKey || mailDept || "general",
    matched: matched.length > 0,
    employees: matched,
    used_fallback: !matchedKey
  };
};

