export const code = async (inputs) => {
  const threadId = (inputs.threadId || "").trim();
  const rows = inputs.rows || [];

  const matchedRow = rows.find((row) => 
    (row.values?.["Thread ID"] || "").trim() === threadId
  );

  const exists = !!matchedRow;
  const rowNumber = matchedRow ? matchedRow.row : null;
  const rowData = matchedRow ? matchedRow.values : null;

  return { exists, rowNumber, rowData };
};

