export const code = async (inputs) => {
  const from = (inputs.from || "").toLowerCase();
  const rows = inputs.rows || [];

  const emailMatch = from.match(/<(.+)>/);
  const email = (emailMatch ? emailMatch[1] : from).trim();
  const domain = "@" + email.split("@")[1];

  const isHighValue = rows.some((row) => {
    const suffix = (row.values?.["Mail suffix"] || "").toLowerCase().trim();
    return suffix === email || suffix === domain;
  });

  return { isHighValue };
};

